class Solution {
    public int[][] imageSmoother(int[][] img) {
        int rows = img.length;
        int cols = img[0].length;
        int[][] prefix = new int[rows + 1][cols + 1];
        for (int r = 1; r <= rows; r++) {
            for (int c = 1; c <= cols; c++) {
                prefix[r][c] = img[r - 1][c - 1]
                        + prefix[r - 1][c]
                        + prefix[r][c - 1]
                        - prefix[r - 1][c - 1];
            }
        }

        int[][] result = new int[rows][cols];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int top = Math.max(0, r - 1);
                int left = Math.max(0, c - 1);
                int bottom = Math.min(rows - 1, r + 1);
                int right = Math.min(cols - 1, c + 1);
                int sum = prefix[bottom + 1][right + 1]
                        - prefix[top][right + 1]
                        - prefix[bottom + 1][left]
                        + prefix[top][left];
                int count = (bottom - top + 1) * (right - left + 1);
                result[r][c] = sum / count;
            }
        }
        return result;
    }
}

class Solution {
    public int[][] imageSmoother(int[][] img) {
        int rows = img.length;
        int cols = img[0].length;
        int[][] result = new int[rows][cols];
        int[] columnSums = new int[cols];
        int[] columnCounts = new int[cols];

        for (int r = 0; r < rows; r++) {
            if (r == 0) {
                addRow(img, 0, columnSums, columnCounts);
                if (rows > 1) {
                    addRow(img, 1, columnSums, columnCounts);
                }
            } else {
                int rowToRemove = r - 2;
                if (rowToRemove >= 0) {
                    removeRow(img, rowToRemove, columnSums, columnCounts);
                }
                int rowToAdd = r + 1;
                if (rowToAdd < rows) {
                    addRow(img, rowToAdd, columnSums, columnCounts);
                }
            }

            int windowSum = 0;
            int windowCount = 0;
            for (int c = 0; c < cols; c++) {
                if (c == 0) {
                    windowSum = columnSums[0];
                    windowCount = columnCounts[0];
                    if (cols > 1) {
                        windowSum += columnSums[1];
                        windowCount += columnCounts[1];
                    }
                } else {
                    int leftColumn = c - 2;
                    if (leftColumn >= 0) {
                        windowSum -= columnSums[leftColumn];
                        windowCount -= columnCounts[leftColumn];
                    }
                    int rightColumn = c + 1;
                    if (rightColumn < cols) {
                        windowSum += columnSums[rightColumn];
                        windowCount += columnCounts[rightColumn];
                    }
                }
                result[r][c] = windowSum / windowCount;
            }
        }
        return result;
    }

    private void addRow(int[][] img, int row, int[] columnSums, int[] columnCounts) {
        for (int c = 0; c < img[0].length; c++) {
            columnSums[c] += img[row][c];
            columnCounts[c]++;
        }
    }

    private void removeRow(int[][] img, int row, int[] columnSums, int[] columnCounts) {
        for (int c = 0; c < img[0].length; c++) {
            columnSums[c] -= img[row][c];
            columnCounts[c]--;
        }
    }
}

class Solution {
    public int[][] imageSmoother(int[][] img) {
        int rows = img.length;
        int cols = img[0].length;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                int sum = 0;
                int count = 0;
                for (int dr = -1; dr <= 1; dr++) {
                    for (int dc = -1; dc <= 1; dc++) {
                        int nr = r + dr;
                        int nc = c + dc;
                        if (0 <= nr && nr < rows && 0 <= nc && nc < cols) {
                            sum += img[nr][nc] & 255;
                            count++;
                        }
                    }
                }
                img[r][c] |= (sum / count) << 8;
            }
        }

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                img[r][c] >>= 8;
            }
        }
        return img;
    }
}
